// Розбір оновлення від Telegram. Telegram шле багато типів подій —
// беремо лише ті три, що нас цікавлять, решту тихо ігноруємо.

const u = $input.first().json.body || $input.first().json || {};

const ACTION = {
  est: { classification: 'business', label: 'Оцінка/замір',   ask_purpose: true  },
  job: { classification: 'business', label: 'Обʼєкт у роботі', ask_purpose: true  },
  sup: { classification: 'business', label: 'Постачальник',    ask_purpose: false },
  per: { classification: 'personal', label: 'Особисте',        ask_purpose: false }
};

if (u.callback_query) {
  const cq = u.callback_query;
  const m = /^c:(\d+):(est|job|sup|per)$/.exec(cq.data || '');
  if (!m) return [{ json: { kind: 'other' } }];
  const a = ACTION[m[2]];
  return [{ json: {
    kind: 'callback',
    callback_query_id: cq.id,
    tg_user_id: cq.from && cq.from.id,
    tg_user_name: [cq.from && cq.from.first_name, cq.from && cq.from.last_name].filter(Boolean).join(' '),
    chat_id: cq.message && cq.message.chat && cq.message.chat.id,
    message_id: cq.message && cq.message.message_id,
    original_text: (cq.message && cq.message.text) || '',
    trip_id: Number(m[1]),
    classification: a.classification,
    action_label: a.label,
    ask_purpose: a.ask_purpose
  } }];
}

const msg = u.message || u.edited_message;
if (!msg) return [{ json: { kind: 'other' } }];

const base = {
  tg_user_id: msg.from && msg.from.id,
  chat_id: msg.chat && msg.chat.id,
  message_id: msg.message_id,
  taken_at: new Date((msg.date || 0) * 1000).toISOString()
};

// Відповідь на картку поїздки = мета цієї поїздки
if (msg.reply_to_message && msg.text) {
  return [{ json: { ...base, kind: 'purpose',
                    reply_to_message_id: msg.reply_to_message.message_id,
                    purpose: msg.text.trim().slice(0, 300) } }];
}

// Фото: беремо найбільший варіант
if (Array.isArray(msg.photo) && msg.photo.length) {
  const best = msg.photo[msg.photo.length - 1];
  const cap = (msg.caption || '').toLowerCase();
  let kind = 'site';
  if (/одометр|odometer|пробіг/.test(cap)) kind = 'odometer';
  else if (/чек|receipt|пальн|fuel/.test(cap)) kind = 'receipt';
  return [{ json: { ...base, kind: 'photo', photo_kind: kind,
                    file_id: best.file_id, caption: msg.caption || null } }];
}

return [{ json: { ...base, kind: 'other' } }];

// Підтвердження у картці + підказка, що робити далі
const src = $('Розбір оновлення').first().json;
const db  = $input.first().json || {};

const mark = db.classification === 'personal' ? '🏠' : '💼';
const lines = [
  src.original_text,
  '',
  `${mark} <b>${src.action_label}</b> · ${db.driver_label || '—'}`
];
if (src.ask_purpose) lines.push('<i>Відповідь на це повідомлення = мета поїздки</i>');
if (db.account_known === false) {
  lines.push(`<i>Акаунт ${src.tg_user_name || src.tg_user_id} ще не привʼязаний до водія — скажи Роману.</i>`);
}

return [{ json: {
  chat_id: src.chat_id,
  message_id: src.message_id,
  callback_query_id: src.callback_query_id,
  toast: src.ask_purpose ? 'Записано. Додай мету відповіддю.' : 'Записано.',
  new_text: lines.join('\n')
} }];

